private function normalizeManifestContract(array $spec,array $productAssets,array $marketingAssets):array|WP_Error{$req=is_array($spec['asset_requirements']??null)?$spec['asset_requirements']:[];$roots=array_values(array_filter(array_map('sanitize_file_name',is_array($req['required_root_files']??null)?$req['required_root_files']:[])));$variantSets=[];foreach($req as$k=>$v){if(str_ends_with((string)$k,'_files')&&is_array($v))$variantSets[(string)$k]=array_values(array_filter(array_map('sanitize_file_name',$v)));}if($variantSets===[])return['product_assets'=>$this->scrubCustomerAssets($productAssets),'marketing_assets'=>$marketingAssets,'selected_variant'=>'unspecified'];$selectedKey='';foreach(['selected_variant_key','delivery_variant_key'] as$k){$candidate=sanitize_key((string)($spec[$k]??''));if(isset($variantSets[$candidate])){$selectedKey=$candidate;break;}}if($selectedKey===''&&isset($variantSets['english_files']))$selectedKey='english_files';if($selectedKey==='')$selectedKey=(string)array_key_first($variantSets);if($selectedKey!=='english_files'&&!$this->hasTranslationReviewEvidence($spec,$selectedKey))return$this->error('production_manifest_contract','Selected translated variant lacks explicit completed human translation-review evidence.',502);$allowed=array_values(array_unique(array_merge($roots,$variantSets[$selectedKey])));$allowedMap=array_fill_keys(array_map('strtolower',$allowed),true);$filtered=[];$seen=[];foreach($productAssets as$a){$name=sanitize_file_name((string)($a['filename']??''));$lower=strtolower($name);if(!isset($allowedMap[$lower]))continue;$a['filename']=$name;$filtered[]=$a;$seen[$lower]=true;}$missing=[];foreach($allowed as$name){if(!isset($seen[strtolower($name)]))$missing[]=$name;}if($missing!==[])return$this->error('production_manifest_contract','Missing required customer files for '.$selectedKey.': '.implode(', ',$missing),502);$pageCount=count(is_array($req['page_structure']??null)?$req['page_structure']:[]);foreach($filtered as&$a){$name=(string)($a['filename']??'');$format=strtolower((string)($a['format']??''));$content=is_string($a['content']??null)?(string)$a['content']:$this->serializedAssetBytes($a);if(strtolower($name)==='readme.txt'){$content=str_ireplace(['marketing_assets_in_customer_package=false','evidence_assets_in_customer_package=false'],['Marketing and listing assets are not included in the customer download.','Machine audit evidence is kept outside the customer download.'],$content);$a['content']=$content;}if($format==='pdf'&&$pageCount>0){$actual=substr_count($content,'[[PAGE_BREAK]]')+1;if($actual!==$pageCount)return$this->error('production_manifest_contract',$name.' must contain exactly '.$pageCount.' pages; manifest contains '.$actual.'.',502);}if($format==='svg'&&preg_match('/(?:inventory\s*marker|source[- ]set\s*(?:explanation|inventory)|page\s*inventory\s*marker)/i',$content))return$this->error('production_manifest_contract',$name.' contains marker/explanatory content instead of the required page artwork.',502);}unset($a);return['product_assets'=>$filtered,'marketing_assets'=>$marketingAssets,'selected_variant'=>$selectedKey];}
