private function normalizeGeneratedEvidence(array $assets):array{foreach($assets as&$a){if(($a['format']??'')==='html'&&is_string($a['content']??null)){$a['content']=preg_replace('/(<label[^>]*>[^<]+<\/label>)\s*(?=<label)/i','$1<br>',$a['content'])??$a['content'];}}unset($a);$hashRows=[];foreach($assets as$a){$name=(string)($a['filename']??'');if($name===''||preg_match('/(?:checksum|manifest_checksums)/i',$name))continue;$hashRows[]=['sha256'=>hash('sha256',$this->serializedAssetBytes($a)),'filename'=>$name];}foreach($assets as&$a){$name=(string)($a['filename']??'');if(!preg_match('/(?:checksum|manifest_checksums)/i',$name))continue;if(strtolower((string)($a['format']??''))==='csv'||preg_match('/\.csv$/i',$name)){$lines=['sha256,filename'];foreach($hashRows as$row)$lines[]=$row['sha256'].','.$row['filename'];$a['content']=implode("\n",$lines)."\n";$a['format']='csv';}else{$a['content']=implode("\n",array_map(static fn(array $row):string=>$row['sha256'].'  '.$row['filename'],$hashRows))."\n";}}unset($a);return$assets;}
private function uniqueDefinitions(array $definitions):true|WP_Error{$keys=[];$files=[];foreach($definitions as$definition){$assetKey=sanitize_key((string)($definition['asset_key']??''));$file=strtolower(sanitize_file_name((string)($definition['filename']??'')));if($assetKey===''||$file==='')return$this->error('production_manifest','Every production asset requires a unique asset_key and filename.',502);if(isset($keys[$assetKey])||isset($files[$file]))return$this->error('production_manifest','AI production manifest contains duplicate asset keys or filenames.',502);$keys[$assetKey]=true;$files[$file]=true;}return true;}
private function productionPrompt(array $developed,string $shop):string{$spec=wp_json_encode($developed['spec']??[],JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);return"Create a production-ready DigiForge asset manifest for a {$shop} Etsy product. Return one JSON object with BOTH required top-level arrays: product_assets and marketing_assets. Neither array may be omitted, null, or empty. Reserve enough output budget for at least one concise listing-only marketing asset after all customer product assets. Keep the complete response comfortably below the provider output limit: generate the minimum sellable asset set, avoid duplicate content across files, and keep each asset concise. Before returning, verify product_assets has at least one item AND marketing_assets has at least one item; if necessary shorten individual content rather than dropping either required group. Preserve every required filename and extension from the approved specification exactly (for example checksums.sha256 must not become checksums.txt). Customer-facing guide/source assets must contain the COMPLETE promised section set and complete final prose in every promised language/variant; never abbreviate, summarize, omit sections, or use authoring instructions. If a guide requires multiple sections/pages, emit explicit page breaks using [[PAGE_BREAK]] between complete pages so the local PDF producer can preserve the intended page structure. Marketing copy may claim only features, files, variants, languages, editability, and completeness that are directly evidenced by emitted production assets. Provenance translation_review_status must never claim human or fluent review unless such review evidence exists. AI generation alone is not translation approval. If translation review is not evidenced, either emit only the approved default-language customer variant or mark alternate translations as unreviewed and exclude them from the customer ZIP and premium/approved marketing claims. Each asset needs unique asset_key, filename, format (html/txt/json/csv/svg/pdf), purpose and complete content. JSON asset content must be a JSON object/array encoded once, never a quoted JSON string containing serialized JSON. Product assets are customer-delivery files; marketing assets are listing-only. The approved product specification is the binding production contract: {$spec}. Do not silently substitute a different deliverable type, editing method, feature set, variant structure, or customer promise. Use HTML format only for complete rendered documents/pages. Never label a stylesheet, CSS fragment, prose note, metadata, or partial markup as HTML; emit those as txt. Every HTML asset must be a complete valid document with <!doctype html>, html, head, a real <style> element, and body; if it claims editable fields, include corresponding labelled input/textarea/select controls for every claimed field. Never emit INSERT, TODO, example.com, placeholder URLs, fake QR destinations or fake Canva links. External-service deliverables such as Canva templates may be claimed only when the specification contains a verified usable URL; otherwise the manifest and ALL marketing copy must explicitly exclude that unavailable capability rather than claim it. PDF deliverables must be emitted as format pdf with complete text/page content so DigiForge generates a real local PDF; never claim interactive/fillable AcroForm fields, save/reopen form behavior, or editable PDF controls because the local producer generates static PDFs. QR, map, RSVP, registry, hotel, or other link functionality may be claimed only when a real approved destination is available; otherwise omit both the functionality and every marketing claim for it. Preserve the approved language editions and variant structure exactly. If the approved specification defines a selected-language or selected-variant customer delivery, emit product_assets ONLY for that selected customer variant; do not bundle alternate language editions into the same customer ZIP. Alternate variants may be described in marketing only when they are separate selectable products/deliveries and must not appear in the selected variant customer_files inventory. If an unavailable external dependency makes a specific capability impossible, remove the same claim consistently from product content, instructions, manifests, previews and listing copy. If marketing promises editable SVG source pages, emit one complete SVG source for every promised guide page, language and paper-size variant, or remove that promise consistently from the specification-facing marketing/instructions. Before returning JSON, cross-check every customer-facing claim against an actual product asset in this manifest. Marketing must describe only what the generated package really contains. Filenames are flat local filenames: never require or advertise nested directory paths, and use the exact same flat filename in the specification-facing manifest and marketing evidence. Every promised language edition must contain complete translated customer-facing prose, not untranslated tokens, heading-only translations, or authoring instructions such as Add/Insert/Replace/Enter; buyer-specific unknown facts must use clearly labelled neutral fields without pretending those facts are prefilled. Optional link, QR, map, RSVP, registry, hotel or transport fields must be omitted everywhere unless a verified destination exists; do not promise blank link fields that are not generated. DigiForge deterministically injects DELIVERY-MANIFEST.json, LICENSE-AND-PROVENANCE.txt and provenance.json after this response, so do not emit those reserved files. For provenance, marketing and instructions may refer to LICENSE-AND-PROVENANCE.txt and provenance.json that truthfully records DigiForge generation, creation context, locally generated text/layout/SVG status, system-font-only status when true, and that no third-party artwork is bundled; do not invent third-party licenses or rights evidence. Avoid unnecessary third-party brand names in customer assets and marketing copy. The customer package ZIP must contain product assets only and must exclude all marketing assets; the delivery manifest must explicitly enumerate the exact customer filenames and state marketing_assets_in_customer_package=false. Marketing assets must not be passed into customer package construction. Do not invent licensing evidence; prefer locally generated text/layout/SVG content. Make all content final, commercially usable and internally consistent. Do not call external services, publish anything, or include scripts/iframes/remote resources.";}
private function error(string $code,string $message,int $status=400):WP_Error{return new WP_Error('digiforge_'.$code,$message,['status'=>$status]);}
}
